# failing line: assert change_base(x, base) == _reference(x, base)
def _reference(x: int, base: int) -> str:
    if x == 0:
        return "0"
    digits = []
    v = x
    while v > 0:
        digits.append(str(v % base))
        v //= base
    return "".join(reversed(digits))

@given(
    x=st.integers(min_value=0, max_value=50_000),
    base=st.integers(min_value=2, max_value=9),
)
def test_equivalence_to_reference_model(x, base):
    assert change_base(x, base) == _reference(x, base)
